INSERT INTO `chat_history` (`id`, `session_id`, `role`, `content`, `created_at`, `sender`) VALUES
(16, 'session_1756654224565_23urom8ghsg', 'user', 'hello', '2025-09-04 04:19:39', 'user'),
(17, 'session_1756654224565_23urom8ghsg', 'user', '```json\n{\"reply\": \"Chào bạn!  Tôi là Nàng thơ bãi biển, rất vui được gặp bạn.  Hãy cùng nhau khám phá những điều kỳ diệu của đại dương nhé!\"}\n```\n', '2025-09-04 04:19:39', 'ai'),
(18, 'session_1756654224565_23urom8ghsg', 'user', 'Bạn giới thiệu cho tôi 1 số bãi biển đẹp ở Hạ Long đi', '2025-09-04 04:20:04', 'user'),
(19, 'session_1756654224565_23urom8ghsg', 'user', '```json\n{\"reply\": \"Chào bạn! Hạ Long nổi tiếng với vẻ đẹp kỳ vĩ của vịnh, nhưng bãi biển riêng biệt thì không nhiều và không phát triển mạnh như các vùng biển khác. Tuy nhiên, bạn vẫn có thể tìm thấy những trải nghiệm thú vị gần biển tại Hạ Long.  Tôi gợi ý bạn tìm hiểu về các bãi tắm nhân tạo hoặc các khu nghỉ dưỡng ven biển có bãi tắm riêng, thường được thiết kế đẹp mắt và sạch sẽ.  Để có trải nghiệm biển hoàn hảo hơn, bạn có thể cân nhắc đến các bãi biển nổi tiếng ở các tỉnh lân cận như Quảng Ninh, Hải Phòng, hay thậm chí xa hơn một chút như các bãi biển ở Thanh Hóa hay Ninh Bình.  Tôi rất sẵn lòng giúp bạn tìm hiểu thêm thông tin về các bãi biển này nếu bạn muốn nhé!\"}\n```\n', '2025-09-04 04:20:04', 'ai'),
(20, 'session_1756654224565_23urom8ghsg', 'user', 'vậy ở đó có j vui không', '2025-09-04 04:20:42', 'user'),
(21, 'session_1756654224565_23urom8ghsg', 'user', '```json\n{\"reply\": \"À, bạn hỏi ở Hạ Long có gì vui không ạ?  Mặc dù bãi biển tự nhiên không quá nổi bật, nhưng Hạ Long vẫn có rất nhiều hoạt động thú vị gần biển đấy! Bạn có thể tham gia các tour du lịch vịnh Hạ Long, ngắm nhìn những hòn đảo đá vôi kỳ vĩ, hang động huyền bí, và tận hưởng không khí trong lành trên biển.  Hoặc bạn cũng có thể lựa chọn những hoạt động thư giãn như chèo thuyền kayak, tắm nắng trên bãi tắm nhân tạo của các khu nghỉ dưỡng, thưởng thức hải sản tươi sống tại các nhà hàng ven biển.  Tùy thuộc vào sở thích của bạn, Hạ Long sẽ mang đến những trải nghiệm khó quên, dù không phải là những bãi biển trải dài cát trắng nhưng vẫn đầy hấp dẫn!\"}\n```\n', '2025-09-04 04:20:42', 'ai'),
(22, 'session_1756654224565_23urom8ghsg', 'user', 'vậy bãi biển nào gần đó', '2025-09-04 04:23:09', 'user'),
(23, 'session_1756654224565_23urom8ghsg', 'user', '```json\n{\"reply\": \"Gần Hạ Long, bạn có thể cân nhắc đến các bãi biển ở Quảng Ninh, một tỉnh liền kề.  Tuy nhiên, các bãi biển ở Quảng Ninh thường không nổi tiếng về chất lượng cát và nước biển như ở các vùng biển miền Trung.  Để có trải nghiệm bãi biển hoàn hảo hơn, bạn có thể xem xét các bãi biển ở các tỉnh khác như Hải Phòng (cũng tương đối gần), hoặc xa hơn một chút như các bãi biển ở Thanh Hóa hay thậm chí Ninh Bình (có những bãi biển nhỏ xinh, tuy nhiên không quá nổi bật).  Bạn muốn tìm hiểu thêm về bãi biển cụ thể ở tỉnh nào không ạ? Tôi có thể cung cấp thông tin chi tiết hơn về các bãi biển đó.\"}\n```\n', '2025-09-04 04:23:09', 'ai'),
(24, 'session_1756654224565_23urom8ghsg', 'user', 'nói chi tiết về bãi biênr Hạ Long', '2025-09-05 04:17:03', 'user'),
(25, 'session_1756654224565_23urom8ghsg', 'user', '```json\n{\"reply\": \"Chào bạn! Như mình đã nói, Hạ Long không nổi tiếng với các bãi biển trải dài cát trắng như ở các vùng biển khác.  Vịnh Hạ Long tập trung vào vẻ đẹp của các hòn đảo đá vôi, hang động và hệ sinh thái biển đa dạng.  Tuy nhiên, nếu bạn muốn tìm trải nghiệm gần biển ở Hạ Long, bạn sẽ tìm thấy các bãi tắm nhân tạo hoặc các khu nghỉ dưỡng ven biển có bãi tắm riêng, thường được thiết kế đẹp mắt và có dịch vụ tốt.  Những bãi tắm này thường không rộng lớn và tự nhiên như các bãi biển truyền thống, nhưng vẫn đáp ứng nhu cầu thư giãn và tắm biển.  Bạn quan tâm đến loại hình bãi tắm nào ở Hạ Long hơn? Có lẽ bạn muốn biết thêm về các khu nghỉ dưỡng có bãi tắm riêng, hay tìm hiểu về các hoạt động vui chơi giải trí gần biển ở Hạ Long? Tôi rất sẵn lòng chia sẻ thêm thông tin nếu bạn cần nhé!\"}\n```\n', '2025-09-05 04:17:19', 'ai'),
(26, 'session_1756654224565_23urom8ghsg', 'user', 'nói chi tiết về bãi biển Hạ Long', '2025-09-05 04:17:35', 'user'),
(27, 'session_1756654224565_23urom8ghsg', 'user', '```json\n{\"reply\": \"Chào bạn!  Như chúng ta đã nói, Hạ Long không nổi tiếng với các bãi biển dài cát trắng như ở các vùng biển khác của Việt Nam. Vẻ đẹp của Hạ Long nằm ở hệ thống hang động, hòn đảo đá vôi kỳ vĩ và hệ sinh thái biển phong phú.  Tuy nhiên, nếu bạn muốn trải nghiệm gần biển ở Hạ Long, bạn sẽ tìm thấy một số bãi tắm nhân tạo hoặc các khu nghỉ dưỡng ven biển có bãi tắm riêng.  Những bãi tắm này thường nhỏ hơn và không tự nhiên như các bãi biển truyền thống, nhưng được thiết kế đẹp mắt, sạch sẽ và cung cấp nhiều dịch vụ tiện nghi.  Bạn có muốn tìm hiểu cụ thể về các khu nghỉ dưỡng có bãi tắm riêng ở Hạ Long, hoặc về các hoạt động giải trí gần biển ở đó không? Tôi rất vui được chia sẻ thêm thông tin chi tiết hơn nếu bạn muốn nhé!\"}\n```\n', '2025-09-05 04:17:35', 'ai'),
(28, 'session_1756654224565_23urom8ghsg', 'user', 'tôi có thể ở khác sạn nào gần đấy nhỉ', '2025-09-05 04:17:54', 'user'),
(29, 'session_1756654224565_23urom8ghsg', 'user', '```json\n{\"reply\": \"Chào bạn!  Tôi hiểu bạn đang tìm kiếm khách sạn gần các bãi biển hoặc khu vực ven biển ở Hạ Long.  Tuy nhiên, để giúp bạn tìm được khách sạn phù hợp nhất, tôi cần thêm một chút thông tin. Bạn có thể cho tôi biết bạn muốn tìm khách sạn ở khu vực nào của Hạ Long không?  Ví dụ, gần trung tâm thành phố, gần khu vực vịnh, hay gần một bãi tắm nhân tạo cụ thể nào đó?  Ngoài ra, bạn có yêu cầu gì về giá cả, loại hình khách sạn (khách sạn lớn, resort, homestay…), hay các tiện nghi khác không?  Càng nhiều thông tin bạn cung cấp, tôi càng có thể giúp bạn tìm được khách sạn lý tưởng nhất, để bạn có một kỳ nghỉ tuyệt vời gần biển ở Hạ Long!\"}\n```\n', '2025-09-05 04:17:54', 'ai'),
(30, 'session_1756654224565_23urom8ghsg', 'user', 'Giới thiệu cho tôi về bãi biển Hạ Long', '2025-09-05 18:15:13', 'user'),
(31, 'session_1756654224565_23urom8ghsg', 'user', '```json\n{\"reply\": \"Hạ Long không nổi tiếng với các bãi biển tự nhiên trải dài như các vùng biển khác ở Việt Nam. Vẻ đẹp của Hạ Long chủ yếu đến từ hệ thống hang động, hòn đảo đá vôi và hệ sinh thái biển đa dạng. Tuy nhiên, tại Hạ Long có các bãi tắm nhân tạo hoặc bãi tắm riêng của các khu nghỉ dưỡng ven biển.  Những bãi tắm này thường quy mô nhỏ hơn, không tự nhiên như các bãi biển truyền thống nhưng được thiết kế và giữ gìn sạch sẽ, cung cấp dịch vụ tiện nghi. Bạn muốn tìm hiểu thêm về các khu nghỉ dưỡng có bãi tắm riêng ở Hạ Long hay các hoạt động giải trí gần biển tại khu vực này không?\"}\n```\n', '2025-09-05 18:15:13', 'ai'),
(32, 'session_1756654224565_23urom8ghsg', 'user', 'Giới thiệu cho tôi về bãi biển Hạ Long', '2025-09-05 18:18:35', 'user'),
(33, 'session_1756654224565_23urom8ghsg', 'user', '```json\n{\"reply\": \"Hạ Long không nổi tiếng với các bãi biển tự nhiên trải dài như các vùng biển khác ở Việt Nam. Vẻ đẹp của Hạ Long chủ yếu đến từ hệ thống hang động, hòn đảo đá vôi và hệ sinh thái biển đa dạng. Tuy nhiên, tại Hạ Long có các bãi tắm nhân tạo hoặc bãi tắm riêng của các khu nghỉ dưỡng ven biển. Những bãi tắm này thường quy mô nhỏ hơn, không tự nhiên như các bãi biển truyền thống nhưng được thiết kế và giữ gìn sạch sẽ, cung cấp dịch vụ tiện nghi. Bạn muốn tìm hiểu thêm về các khu nghỉ dưỡng có bãi tắm riêng ở Hạ Long hay các hoạt động giải trí gần biển tại khu vực này không?\"}\n```\n', '2025-09-05 18:18:35', 'ai'),
(34, 'session_1756654224565_23urom8ghsg', 'user', 'Giới thiệu cho tôi về bãi biển Hạ Long', '2025-09-05 18:31:06', 'user'),
(35, 'session_1756654224565_23urom8ghsg', 'user', '```json\n{\"reply\": \"Hạ Long không nổi tiếng với các bãi biển tự nhiên rộng lớn. Vẻ đẹp của Hạ Long chủ yếu đến từ vịnh với nhiều đảo đá vôi và hang động. Tuy nhiên, một số khu nghỉ dưỡng ven biển có bãi tắm nhân tạo hoặc bãi tắm riêng, thường nhỏ hơn và không tự nhiên như các bãi biển truyền thống. Gợi ý truy vấn:  Thông tin về các bãi biển ở Nha Trang.\"}\n```\n', '2025-09-05 18:31:06', 'ai'),
